mapper.select:
select t.id as id, t.name as name, t.slug as slug, count(distinct c.id) as count from cms_tag t join cms_content_tag ct on ct.tag_id = t.id and ct.deleted = 0 join cms_content c on c.id = ct.content_id where t.site_id = #{p.siteId} and t.deleted = 0 and c.site_id = #{p.siteId} and c.deleted = 0
group by t.id, t.name, t.slug having count(distinct c.id) >= #{minCount}
order by t.name asc, t.id asc order by t.id asc order by count(distinct c.id) desc, t.id asc
limit #{limit}
